def sudoku_valid(board) -> bool:
    if not isinstance(board, list) or len(board) != 9:
        raise ValueError("Board must be a 9x9 list of lists")

    for row in board:
        if not isinstance(row, list) or len(row) != 9:
            raise ValueError("Board must be a 9x9 list of lists")
        for value in row:
            if not isinstance(value, int) or isinstance(value, bool) or not 0 <= value <= 9:
                raise ValueError("Board values must be integers from 0 to 9")

    for row in board:
        values = [value for value in row if value != 0]
        if len(values) != len(set(values)):
            return False

    for col in range(9):
        values = [board[row][col] for row in range(9) if board[row][col] != 0]
        if len(values) != len(set(values)):
            return False

    for box_row in range(0, 9, 3):
        for box_col in range(0, 9, 3):
            values = [
                board[row][col]
                for row in range(box_row, box_row + 3)
                for col in range(box_col, box_col + 3)
                if board[row][col] != 0
            ]
            if len(values) != len(set(values)):
                return False

    return True
